# Add a person. Validate first so an empty name or bad grade is refused (400) and writes nothing;
# then refuse a name already in use on the sheet.
validate:
  class: net.officefloor.hq.app.person.ValidatePerson
  next: build
build:
  class: net.officefloor.hq.app.person.BuildPerson
  next: check
check:
  class: net.officefloor.hq.app.person.CheckPersonName
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.person.SavePerson
  govern: [ transaction ]
  next: audit
# Record the change only once it is saved, so a refused change writes no audit line.
audit:
  class: net.officefloor.hq.app.person.AuditPersonAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
== ValidatePerson
package net.officefloor.hq.app.person;

import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the person from the body, refusing an empty name or a grade other than A, B or C. */
public class ValidatePerson {

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> personOut)
            throws InvalidPersonException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A person needs a name.");
        }
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        personOut.set(new PersonRequest(name, grade, request.version()));
    }
}
== BuildPerson
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class BuildPerson {
    public void build(@PathVariable("sheetId") String sheetId, @Val PersonRequest request, Out<Person> personOut) {
        Person person = new Person(sheetId.trim());
        person.setName(request.name());
        person.setGrade(request.grade());
        personOut.set(person);
    }
}
== CheckPersonName
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** Refuses a name already used by another person on the sheet (ignoring case; names are trimmed). */
public class CheckPersonName {
    public void check(@Val PersonRequest request, @Val Person person, PersonRepository repository)
            throws InvalidPersonException {
        boolean taken = repository.findBySheetIdOrderByIdAsc(person.getSheetId()).stream()
                .anyMatch((other) -> !other.getId().equals(person.getId())
                        && other.getName().equalsIgnoreCase(request.name()));
        if (taken) {
            throw new InvalidPersonException("The name " + request.name() + " is already in use on this sheet.");
        }
    }
}
== SavePerson
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

public class SavePerson {
    public void save(@Val Person person, PersonRepository repository) {
        repository.saveAndFlush(person); // flushed so the response carries the raised version
    }
}
== AuditPersonAdded
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.HttpHeaderParameter;

/** Records PERSON_ADDED once the person is saved; the signed-in user arrives as X-User. */
public class AuditPersonAdded {
    public void audit(@Val Person person, @HttpHeaderParameter("X-User") String user, Audit audit) {
        audit.record(PersonAudit.line("PERSON_ADDED", person, user));
    }
}
== PersonAudit
package net.officefloor.hq.app.person;

/** The audit line for a saved person: the event, sheet and user, then name and grade. */
final class PersonAudit {
    private PersonAudit() {
    }

    static String line(String event, Person person, String user) {
        return event + " sheet=" + person.getSheetId() + " by=" + (user == null ? "" : user.trim())
                + " name=" + person.getName() + " grade=" + person.getGrade();
    }
}
== RespondWithPerson
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, ObjectResponse<PersonResponse> response) {
        response.send(PersonResponse.from(person));
    }
}
